     "comentario": "<p>A alternativa D está correta. Mesmo com peso reduzido, a volatilidade de 60% e a covariância com ações contribuem para o risco, que passou de 9,77% para 10,39% nas premissas usadas.</p><p>A alternativa A inventa um limite de peso para entrada no cálculo. A alternativa B trata uma correlação isolada como eliminação de risco. A alternativa C confunde retorno observado com medida de volatilidade.</p><p>Regra de bolso: peso pequeno controla a contribuição, mas volatilidade e correlação continuam atuando.</p>",
     "enunciado": "<p>Na simulação da carteira 57/38/5, a parcela cripto apresenta volatilidade de 60%, contra 15% das ações e 6% da renda fixa. Com correlação de 0,25 entre ações e cripto e de zero entre renda fixa e cripto, a volatilidade calculada passa de 9,77% para 10,39%. O cliente conclui que uma fatia de 5% é pequena demais para alterar o risco. Analise o resultado e sua dependência das premissas.</p>",
