     "comentario": "<p>A alternativa C está correta. A análise começa pela função da parcela, pelo orçamento de perda, horizonte e liquidez; depois define peso e acesso compatíveis com conhecimento, custódia e capacidade de lidar com margem.</p><p>A alternativa A trata margem como redução de risco e ignora chamadas. A alternativa B transforma uma simulação em definição de peso. A alternativa D presume eliminação de risco pela autocustódia e deixa o objetivo fora da decisão.</p><p>Regra de bolso: objetivo e perda suportável vêm antes do peso; custódia e veículo vêm depois.</p>",
     "enunciado": "<p>Um cliente possui R$ 800 mil numa carteira 60/40 destinada à aposentadoria em quatro anos. Após ver uma simulação favorável, pede 20% em bitcoin e ether por meio de contratos futuros, embora desconheça chamadas de margem e precise preservar liquidez para despesas. Ele também demonstra desconforto com chaves privadas. O profissional precisa decidir a sequência da análise, o limite de risco e a forma de acesso antes de indicar qualquer posição. Analise a condução adequada.</p>",
